import{c as a,$ as n,Q as r,j as s,g as t,o,n as l,m as c}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Licenses & Limitations","description":"Practical guide to OmniCraft ERP licensing tiers, the Free trial limit, offline cryptographic security, and multi-device management.","frontmatter":{"title":"Licenses & Limitations","description":"Practical guide to OmniCraft ERP licensing tiers, the Free trial limit, offline cryptographic security, and multi-device management.","datePublished":"2026-10-28","dateModified":"2026-11-17","order":23},"headers":[],"relativePath":"docs/licenses.md","filePath":"docs/licenses.md","lastUpdated":1794873600000}'),d={name:"docs/licenses.md"},h={id:"licenses-limitations-fair-trial-licensing-tiers-and-offline-security",tabindex:"-1"};function p(u,e,g,y,m,f){const i=n("DocIcon");return r(),s("div",null,[t("h1",h,[o(i,{name:"licenses"}),e[0]||(e[0]=l(" Licenses & Limitations: Fair Trial, Licensing Tiers, and Offline Security ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#licenses-limitations-fair-trial-licensing-tiers-and-offline-security","aria-label":'Permalink to "Licenses & Limitations: Fair Trial, Licensing Tiers, and Offline Security"'},"​",-1))]),e[2]||(e[2]=c('<p>For an artisan, service technician, or boutique workshop owner, software is an essential work tool—not an excuse for unpredictable recurring monthly fees. If a cloud vendor decides to alter their pricing, suspend an account, or suffer an outage, the business risks immediate loss of access to its customer records and financial ledgers.</p><p>OmniCraft ERP is built on a fundamentally different architectural model:</p><ul><li><strong>Local Data Sovereignty:</strong> the software operates as a self-contained desktop application for Windows. The database resides strictly on your physical machine, guaranteeing complete privacy for your operational trade secrets;</li><li><strong>Unrestricted Fair Trial:</strong> the evaluation version never disables planning tools, hides inventory sheets, or locks balance reports. You receive a fully functional system for testing under genuine workshop conditions;</li><li><strong>Transparent Growth Path:</strong> a commercial license lifts the single trial limit and unlocks multi-business scaling as your trade expands.</li></ul><hr><h2 id="three-licensing-tiers" tabindex="-1">Three Licensing Tiers <a class="header-anchor" href="#three-licensing-tiers" aria-label="Permalink to &quot;Three Licensing Tiers&quot;">​</a></h2><p>The software provides a clear progression of capabilities with no hidden clauses or predatory recurring microtransactions:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Capabilities and Workspaces</th><th style="text-align:center;">🆓 Free Trial ($ 0)</th><th style="text-align:center;">🥈 Standard</th><th style="text-align:center;">👑 Professional (&quot;PRO&quot;)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Core Workshop Modules</strong> (assets, inventory, recipe calculator, workbench, finished goods, web store)</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td></tr><tr><td style="text-align:left;"><strong>Financial Accounting Loops</strong> (cash flow / DDS, management balance, analytics)</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td></tr><tr><td style="text-align:left;"><strong>Retail Sales Processing Limit</strong></td><td style="text-align:center;">Up to 20 receipts</td><td style="text-align:center;">Unlimited</td><td style="text-align:center;">Unlimited</td></tr><tr><td style="text-align:left;"><strong>Backups &amp; Security</strong> (WAL transaction protection, backup rotation)</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td><td style="text-align:center;">Full access</td></tr><tr><td style="text-align:left;"><strong>Simultaneous Active Workspaces</strong></td><td style="text-align:center;">1 active (switch via archive)</td><td style="text-align:center;">1 active (switch via archive)</td><td style="text-align:center;">Unlimited (multi-workspaces)</td></tr><tr><td style="text-align:left;"><strong>Unarchiving Workspaces</strong></td><td style="text-align:center;">Requires PRO tier</td><td style="text-align:center;">Requires PRO tier</td><td style="text-align:center;">Instant 1-click restore</td></tr><tr><td style="text-align:left;"><strong>Global &quot;My Capital&quot; Suite</strong> (personal accounts, portfolio, personal property)</td><td style="text-align:center;">Not available</td><td style="text-align:center;">Not available</td><td style="text-align:center;">Full access</td></tr><tr><td style="text-align:left;"><strong>Specialized Marketplace Modules</strong></td><td style="text-align:center;">Not available</td><td style="text-align:center;">Add-on purchases available</td><td style="text-align:center;">Add-on purchases available</td></tr></tbody></table><hr><h2 id="workspace-architecture-licensing-guidelines" tabindex="-1">Workspace Architecture: Licensing Guidelines <a class="header-anchor" href="#workspace-architecture-licensing-guidelines" aria-label="Permalink to &quot;Workspace Architecture: Licensing Guidelines&quot;">​</a></h2><p>OmniCraft ERP enables flexible workspace configuration (&quot;Production&quot; or &quot;Services&quot;) right from the initial cold start:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="18" height="18" x="3" y="3" rx="2"></rect><path d="M3 9h18"></path><path d="M9 21V9"></path></svg></span><span><strong>Single Active Workspace on Free and Standard Tiers:</strong> designed for managing one complete enterprise (such as a leathercraft studio or watch repair center).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 8v13H3V8"></path><path d="M1 3h22v5H1z"></path><path d="M10 12h4"></path></svg></span><span><strong>Industry Pivots via Archive:</strong> if your trade focus changes or you wish to start accounting fresh, the active enterprise is moved to the archive, freeing the slot to create a new workspace.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>15-Minute Accidental Archive Safety Window:</strong> clicking the archive button triggers a 15-minute grace period where you can restore the workspace to active status immediately free of charge.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"></path></svg></span><span><strong>Why Unarchiving Requires PRO:</strong> unrestricted unarchiving on the Standard tier would allow serial rotation of dozens of separate businesses under a single entry license. Running multiple simultaneous or alternating operations is specifically supported under the PRO license.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" x2="12" y1="15" y2="3"></line></svg></span><span><strong>Complete Data Liberation:</strong> database backups (.db, .zip) and CSV table exports remain freely accessible and downloadable from archived spaces at any time without paying for a license.</span></li></ul><hr><h2 id="how-the-free-limit-works-20-sales-transactions" tabindex="-1">How the Free Limit Works (20 Sales Transactions) <a class="header-anchor" href="#how-the-free-limit-works-20-sales-transactions" aria-label="Permalink to &quot;How the Free Limit Works (20 Sales Transactions)&quot;">​</a></h2><p>The evaluation version of OmniCraft ERP differs sharply from typical crippled demo software. Every calculation model, recipe sheet, material consumption norm, and inventory report remains fully accessible.</p><p>The only boundary is placed at the <strong>very end of the production pipeline</strong>—the moment payment is registered from a client.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Material Intake] ➔ [Recipe Calculation] ➔ [Workbench Assembly] ➔ [Sales Receipt]</span></span>\n<span class="line"><span>       ✅                   ✅                     ✅              ⚠️ Up to 20 receipts</span></span></code></pre></div><h3 id="what-happens-when-the-limit-is-reached" tabindex="-1">What Happens When the Limit Is Reached <a class="header-anchor" href="#what-happens-when-the-limit-is-reached" aria-label="Permalink to &quot;What Happens When the Limit Is Reached&quot;">​</a></h3><p>When the processed sales counter in the &quot;Sales&quot; tab reaches <strong>20 transactions</strong>, the software automatically switches the sales recording engine to read-only protection:</p><ul><li><strong>Blocked Checkout Operations:</strong> the <strong>&quot;Process Sale&quot;</strong> button in the POS terminal and the <strong>&quot;Complete Production&quot;</strong> button on the workbench become disabled. A top banner appears inviting you to activate a commercial license;</li><li><strong>Unrestricted Inspection and Planning:</strong> you can freely review analytics, add materials, craft new recipe bills of materials, evaluate margin charts, and export backups;</li><li><strong>Zero Historical Data Loss:</strong> no data is erased. Entering a commercial key immediately unlocks the sales register with all past records preserved.</li></ul><h3 id="economic-safeguards-against-trial-tampering" tabindex="-1">Economic Safeguards Against Trial Tampering <a class="header-anchor" href="#economic-safeguards-against-trial-tampering" aria-label="Permalink to &quot;Economic Safeguards Against Trial Tampering&quot;">​</a></h3><p>In typical software, users attempt to reset trials by clearing historical tables. In OmniCraft ERP, doing so is <strong>economically self-defeating</strong>.</p><p>The entire value of management accounting lies in continuous, unbroken historical records. If an artisan manually deletes sales transactions to reset the counter, the system experiences structural disconnections that break:</p><ol><li><strong>The Management Balance Sheet (&quot;Capital&quot;):</strong> distortion of equity calculations and net worth metrics;</li><li><strong>Cash Flow Records (&quot;Cash Flow / DDS&quot;):</strong> real bank and cash drawer balances diverge from the software register;</li><li><strong>FIFO Batch Cost Accounting:</strong> inventory valuations of remaining finished stock become inaccurate;</li><li><strong>Profitability Analytics:</strong> revenue history and break-even point charts are wiped clean.</li></ol><p>Consequently, craftsmen are personally invested in the integrity and continuity of their operational database. Purchasing a license is not merely a software unlock, but an investment in protecting the digital foundation of your craft.</p><hr><h2 id="offline-cryptographic-security-and-privacy-zero-pii" tabindex="-1">Offline Cryptographic Security and Privacy (Zero-PII) <a class="header-anchor" href="#offline-cryptographic-security-and-privacy-zero-pii" aria-label="Permalink to &quot;Offline Cryptographic Security and Privacy (Zero-PII)&quot;">​</a></h2><p>OmniCraft ERP is a local-first desktop application. It never transmits operational ledgers or financial transactions to remote servers. License verification is executed <strong>100% autonomously</strong> without continuous network connectivity.</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Licensing Server (Online Issuance)</th><th style="width:50%;">Craftsman Machine (Offline Validation)</th></tr></thead><tbody><tr><td><ol class="craft-list-steps" style="margin:0;"><li><div><strong>Hardware Signature:</strong> Ingests masked non-PII machine hash.</div></li><li><div><strong>Cryptographic Signing:</strong> Signs payload with private cryptographic key.</div></li><li><div><strong>License Key Issue:</strong> Generates standalone offline license certificate.</div></li></ol></td><td><ol class="craft-list-steps" style="margin:0;"><li><div><strong>Enter Key:</strong> Paste certificate in the application settings modal.</div></li><li><div><strong>Public-Key Verification:</strong> Mathematical check via embedded public key.</div></li><li><div><strong>Instant Activation:</strong> Unlocks all features without internet connection.</div></li></ol></td></tr></tbody></table><h3 id="_1-computer-hardware-signature" tabindex="-1">1. Computer Hardware Signature <a class="header-anchor" href="#_1-computer-hardware-signature" aria-label="Permalink to &quot;1. Computer Hardware Signature&quot;">​</a></h3><p>Upon initial launch, the program computes a unique hardware fingerprint using motherboard parameters and operating system registry entries:</p><ul><li><strong>Sub-Millisecond Execution:</strong> hardware signature calculation requires under 0.1 milliseconds and never delays application startup;</li><li><strong>Complete Anonymity:</strong> the signature is a masked hexadecimal string (e.g., <code>A1B2-C3D4-E5F6-G7H8</code>). It contains no account names, emails, passwords, network addresses, or filenames;</li><li><strong>Privacy Compliance:</strong> the billing architecture eliminates the gathering, storage, or processing of personal data (fully GDPR/CCPA compliant).</li></ul><h3 id="_2-asymmetric-public-key-cryptography" tabindex="-1">2. Asymmetric Public-Key Cryptography <a class="header-anchor" href="#_2-asymmetric-public-key-cryptography" aria-label="Permalink to &quot;2. Asymmetric Public-Key Cryptography&quot;">​</a></h3><p>To prevent tampering and key counterfeiting, asymmetric public-key cryptography protects the system:</p><ul><li><strong>Embedded Public Key:</strong> compiled directly into the application binary. It is mathematically capable only of <em>verifying</em> digital signatures, never generating them;</li><li><strong>Isolated Private Key:</strong> stored securely on the isolated licensing infrastructure and never distributed with client binaries.</li></ul><h3 id="_3-anonymous-license-tokens" tabindex="-1">3. Anonymous License Tokens <a class="header-anchor" href="#_3-anonymous-license-tokens" aria-label="Permalink to &quot;3. Anonymous License Tokens&quot;">​</a></h3><p>Purchasing a license requires no intrusive registration forms or phone verifications. The billing server generates an anonymous token formatted as <code>LIC-XXXX-XXXX-XXXX</code>, linking only the license tier and a list of approved hardware hashes.</p><p>Every commercial license allows simultaneous activation on <strong>up to 5 computers</strong> (e.g., workshop desktop, laptop, and front-desk order terminal).</p><hr><h2 id="device-management-and-self-service" tabindex="-1">Device Management and Self-Service <a class="header-anchor" href="#device-management-and-self-service" aria-label="Permalink to &quot;Device Management and Self-Service&quot;">​</a></h2><p>If a workshop laptop breaks or you upgrade to a faster workstation, you do not need to purchase another license.</p><p>The built-in self-service system lets you release device slots via two convenient methods:</p><div class="craft-window-frame" data-title="License Devices (2 of 5 active)"><div style="padding:1rem 1.25rem;"><table class="craft-matrix-table" style="margin:0;"><thead><tr><th style="width:45%;">Device</th><th style="width:35%;">Hardware Identifier</th><th style="width:20%;">Status</th></tr></thead><tbody><tr><td><strong>Workshop Laptop</strong><br><span style="opacity:0.7;font-size:0.85em;">Current Machine</span></td><td><code>A1B2-C3D4-E5F6-G7H8</code></td><td><span style="color:#10b981;font-weight:600;">● Active</span></td></tr><tr><td><strong>Old Assembly Machine</strong><br><span style="opacity:0.7;font-size:0.85em;">Secondary Workstation</span></td><td><code>F9E8-D7C6-B5A4-9988</code></td><td><span style="opacity:0.8;">[ Unbind ]</span></td></tr></tbody></table></div></div><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><rect width="20" height="14" x="2" y="3" rx="2"></rect><line x1="8" y1="21" x2="16" y2="21"></line><line x1="12" y1="17" x2="12" y2="21"></line></svg></span><span><strong>In-App Device Manager:</strong> in the &quot;Settings&quot; dialog, click the <strong>&quot;Devices&quot;</strong> button. The dialog lists all active workstations with a 1-click unbind option for decommissioned computers.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="2" y1="12" x2="22" y2="12"></line><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"></path></svg></span><span><strong>Website Self-Service Portal:</strong> if an old machine suffered hardware failure, navigate to the license portal on the official website, input your token `LIC-XXXX-XXXX-XXXX`, and remove the dead device without waiting for customer support.</span></li></ul><hr><h2 id="step-by-step-guide-activating-your-license" tabindex="-1">Step-by-Step Guide: Activating Your License <a class="header-anchor" href="#step-by-step-guide-activating-your-license" aria-label="Permalink to &quot;Step-by-Step Guide: Activating Your License&quot;">​</a></h2><p>The activation procedure takes less than one minute and requires zero technical background:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"></circle><polyline points="12 6 12 12 16 14"></polyline></svg></span><span><strong>Step 1: Copy Your Hardware Signature.</strong> Open &quot;Settings&quot; from the application menu. Locate your hardware signature in the &quot;License Management&quot; card and click the copy icon.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"></path><path d="M3 6h18"></path><path d="M16 10a4 4 0 0 1-8 0"></path></svg></span><span><strong>Step 2: Obtain Your Key or Token.</strong> During checkout on the website, paste your hardware signature into the order form. You will receive an anonymous license token or an encoded text license key.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Step 3: Activate the Software.</strong> Paste your key or token into the input field in Settings and click the <strong>&quot;Activate&quot;</strong> button.</span></li></ul><div class="tip custom-block"><p class="custom-block-title">Dynamic Window Title Status</p><p>Activating your key requires no application restart. The Windows title bar updates dynamically: changing from the trial badge to the active commercial tier: <em>OmniCraft ERP (Standard)</em> or <em>OmniCraft ERP (PRO)</em>, alongside the count of active trade extensions.</p></div><hr><h2 id="workshop-frequently-asked-questions" tabindex="-1">Workshop Frequently Asked Questions <a class="header-anchor" href="#workshop-frequently-asked-questions" aria-label="Permalink to &quot;Workshop Frequently Asked Questions&quot;">​</a></h2><h3 id="is-an-active-internet-connection-required-to-verify-the-license" tabindex="-1">Is an active internet connection required to verify the license? <a class="header-anchor" href="#is-an-active-internet-connection-required-to-verify-the-license" aria-label="Permalink to &quot;Is an active internet connection required to verify the license?&quot;">​</a></h3><p>No. Cryptographic key verification is performed locally by the embedded security engine on your PC. An internet connection is used only during the initial 1-second online token binding. All subsequent day-to-day operations run 100% offline.</p><h3 id="what-happens-to-my-historical-records-when-a-subscription-expires" tabindex="-1">What happens to my historical records when a subscription expires? <a class="header-anchor" href="#what-happens-to-my-historical-records-when-a-subscription-expires" aria-label="Permalink to &quot;What happens to my historical records when a subscription expires?&quot;">​</a></h3><p>All your databases, bills of materials, warehouse stock levels, and transaction histories remain completely intact on your local drive. The software never restricts access to historical data or deletes records. If a subscription period concludes, the app simply switches the POS checkout into read-only mode until renewed.</p><h3 id="on-how-many-machines-can-i-use-a-single-license" tabindex="-1">On how many machines can I use a single license? <a class="header-anchor" href="#on-how-many-machines-can-i-use-a-single-license" aria-label="Permalink to &quot;On how many machines can I use a single license?&quot;">​</a></h3><p>Each commercial license includes 5 distinct hardware slots. You can install the application on your workshop desktop, mobile laptop, and home PC. If a computer is replaced, unbind the old slot in the &quot;Devices&quot; dialog and activate your new machine.</p><h3 id="how-do-i-upgrade-from-standard-to-pro" tabindex="-1">How do I upgrade from Standard to PRO? <a class="header-anchor" href="#how-do-i-upgrade-from-standard-to-pro" aria-label="Permalink to &quot;How do I upgrade from Standard to PRO?&quot;">​</a></h3><p>You never need to repurchase the software at full price. In the License Settings card, click the <strong>&quot;Upgrade to PRO&quot;</strong> button: a checkout portal opens with automatic credit for your existing tier, allowing you to pay only the price difference.</p>',58))])}const k=a(d,[["render",p]]);export{b as __pageData,k as default};
